(function(root){'use strict';
const specs=i=>i.variant_specs||{};
const size=i=>{const s=specs(i);return s.diameterCm?'دایره، قطر '+s.diameterCm:s.widthCm&&s.heightCm?s.widthCm+'×'+s.heightCm:'';};
const label=i=>[specs(i).color,size(i),specs(i).thicknessMm?'قطر / ضخامت '+specs(i).thicknessMm+' میلی‌متر':''].filter(Boolean).join(' · ');
function groups(items){const map=new Map();for(const item of items||[]){const s=specs(item),id=s.baseId||item.id;let g=map.get(id);if(!g){g={id,model:s.baseModel||item.model||item.title,material:s.material||'',description:item.description||'',category:item.category,variants:[],rows:[]};map.set(id,g)}g.rows.push(item);if(!s.archived){if(!g.variants.length){g.model=s.baseModel||item.model||item.title;g.material=s.material||'';g.description=item.description||'';g.category=item.category;}g.variants.push(item);}}return [...map.values()];}
function version(items){return JSON.stringify(items.filter(x=>!x.variant_specs?.archived).map(x=>[String(x.id),x.updated_at?new Date(x.updated_at).toISOString():'',String(x.variant_specs?.modelRevision||''),Number(x.sale_price||0),x.active!==false]).sort((a,b)=>a[0].localeCompare(b[0])));}
function colorHex(value){const raw=String(value||'').trim();if(/^#[0-9a-f]{6}$/i.test(raw))return raw.toLowerCase();return ({'قرمز':'#ef4444','آبی':'#2563eb','ابي':'#2563eb','مشکی':'#000000','سفید':'#ffffff','سبز':'#16a34a','زرد':'#facc15','طلایی':'#d4af37','نقره‌ای':'#c0c0c0','قهوه‌ای':'#92400e','صورتی':'#ec4899','خاکستری':'#808080','کرم':'#fff4d1','بنفش':'#9333ea'})[raw]||'#808080';}
const pricingKey=i=>{const s=specs(i);return JSON.stringify([s.widthCm??null,s.heightCm??null,s.diameterCm??null,s.thicknessMm??null]);};
function modelColors(g){return [...new Set(g.variants.flatMap(i=>i.variant_specs?.modelColors||[i.variant_specs?.color]).filter(Boolean))];}
function pricingRows(g){const map=new Map();for(const item of g.variants){const key=pricingKey(item);let entry=map.get(key);if(!entry){entry={item,rows:[],conflict:false};map.set(key,entry);}entry.rows.push(item);if(Number(item.sale_price)!==Number(entry.item.sale_price))entry.conflict=true;}return [...map.values()];}
function compareSpecs(a,b){const x=specs(a),y=specs(b);for(const key of ['diameterCm','widthCm','heightCm','thicknessMm']){const diff=Number(x[key]||0)-Number(y[key]||0);if(diff)return diff;}return String(x.material||'').localeCompare(String(y.material||''),'fa')||String(a.id).localeCompare(String(b.id));}
function cardColors(g){const configured=g.variants.find(x=>Array.isArray(specs(x).modelColors))?.variant_specs.modelColors;return configured||[...new Set(g.variants.map(x=>specs(x).color))].sort((a,b)=>String(a).localeCompare(String(b),'fa'));}
function choose(g,id){const selected=g.variants.find(x=>String(x.id)===String(id));if(selected)return selected;const first=cardColors(g).find(color=>g.variants.some(x=>specs(x).color===color)),rows=g.variants.filter(x=>specs(x).color===first);return rows.sort(compareSpecs)[0]||g.variants[0];}
function changeChoice(g,current,key,value){let rows=g.variants;const material=current.variant_specs?.material||g.material;if(key==='material')rows=rows.filter(x=>(x.variant_specs?.material||g.material)===value);else rows=rows.filter(x=>(x.variant_specs?.material||g.material)===material);if(key==='color')rows=rows.filter(x=>x.variant_specs?.color===value);else if(key!=='material')rows=rows.filter(x=>x.variant_specs?.color===current.variant_specs?.color);if(key==='size')rows=rows.filter(x=>size(x)===value);else if(key==='thickness')rows=rows.filter(x=>size(x)===size(current)&&String(x.variant_specs?.thicknessMm??'')===value);return rows.find(x=>size(x)===size(current)&&String(x.variant_specs?.thicknessMm??'')===String(current.variant_specs?.thicknessMm??''))||rows.sort(compareSpecs)[0];}
function photo(item){return item?.color_image_urls?.[0]||item?.thumbnail_url||item?.thumbnail_urls?.[0]||item?.image_url||item?.image_urls?.[0]||item?.gallery_images?.find(x=>x.url)?.url||'';}
function price(amount,{money,esc}){const formatted=String(money(amount)),match=formatted.match(/^(.*?)(\s*)تومان$/u);if(!match)return esc(formatted);return '<span class="frameMoney" dir="rtl"><span>'+esc(match[1])+'</span>'+esc(match[2])+'<span class="frameToman">تومان</span></span>';}
function card(g,id,{esc,money,owner=false}={}){const i=choose(g,id);if(!i)return '';const s=specs(i),material=s.material||g.material,materialRows=g.variants.filter(x=>(specs(x).material||g.material)===material),materials=[...new Set(g.variants.map(x=>specs(x).material||g.material))],colors=cardColors(g).filter(color=>materialRows.some(x=>specs(x).color===color)),colorRows=materialRows.filter(x=>specs(x).color===s.color).sort(compareSpecs),sizes=[...new Set(colorRows.map(size))],thicknesses=[...new Set(colorRows.filter(x=>size(x)===size(i)).map(x=>String(specs(x).thicknessMm??'')))];
 const select=(key,label,values,current)=>'<label>'+label+'<select data-frame-choice="'+key+'">'+values.map(value=>'<option value="'+esc(value)+'"'+(value===current?' selected':'')+'>'+esc(value||'بدون قطر / ضخامت')+'</option>').join('')+'</select></label>';
 const source=photo(i)?i:g.variants.find(x=>specs(x).color===s.color&&photo(x))||g.variants.find(photo),image=photo(source);
 const swatches='<div class="frameColorChoices" role="group" aria-label="انتخاب رنگ قاب">'+colors.map(color=>'<button type="button" data-frame-choice="color" data-frame-color="'+esc(color)+'" class="frameColorCircle" aria-label="رنگ '+esc(color)+'" aria-pressed="'+(color===s.color)+'" title="رنگ '+esc(color)+'" style="--frame-color:'+colorHex(color)+'"></button>').join('')+'</div>';
 return '<article class="saleItemCard frameStoreModel frameProductCard'+(owner?' frameBaseCard saleCard categoryFiltered':'')+'" data-frame-model="'+esc(g.id)+'" data-selected-item="'+esc(i.id)+'" data-category="'+esc(g.category)+'" data-brand=""><div class="saleItemHead">'+(image?'<button type="button" class="pb834ShopGalleryBtn" data-frame-show-gallery="'+esc(source.id)+'"><img class="saleItemPhoto" src="'+esc(image)+'" alt="'+esc(g.model+' · '+label(i))+'" loading="lazy"></button>':'<span class="saleItemPhotoPlaceholder">⌁</span>')+'<div class="saleItemInfo"><b>'+esc(g.model)+'</b><small>جنس: '+esc(material)+'</small></div></div>'+(g.description?'<p class="frameSharedDescription">'+esc(g.description)+'</p>':'')+(s.color&&size(i)?'<div class="frameStoreChoices">'+(materials.length>1?select('material','جنس',materials,material):'')+swatches+select('size','سایز',sizes,size(i))+(s.sizeOnly?(s.thicknessMm?'<small>قطر قاب: '+esc(s.thicknessMm)+' میلی‌متر</small>':''):select('thickness','قطر / ضخامت (میلی‌متر)',thicknesses,String(s.thicknessMm??'')))+'</div>':'')+'<div class="saleItemPrice" aria-live="polite">'+price(i.sale_price,{money,esc})+'</div>'+(owner?'<div class="frameOwnerActions"><button type="button" class="btn" data-frame-edit-model="'+esc(g.id)+'">ویرایش</button><button type="button" class="frameDeleteModel" data-frame-delete-model="'+esc(g.id)+'">حذف مدل</button><span data-frame-card-message role="status"></span></div>':'<div class="saleItemBuy"><button class="btn" type="button" data-add-sale-cart="'+esc(i.id)+'">افزودن به سبد</button><label class="field"><span>تعداد</span><span class="qtyStepperV810"><button type="button" data-sale-qty-delta="-1" data-sale-qty-id="'+esc(i.id)+'">−</button><input id="saleQty-'+esc(i.id)+'" type="number" min="1" max="99" value="1" inputmode="numeric"><button type="button" data-sale-qty-delta="1" data-sale-qty-id="'+esc(i.id)+'">+</button></span></label></div>')+'</article>';
}
function cardStyles(){return '.frameMoney{display:inline-flex;align-items:center;gap:5px;white-space:nowrap}.frameToman{display:inline-block;position:relative;width:2.3em;height:1.7em;font-size:.62em;font-weight:800;line-height:1;color:transparent;vertical-align:middle}.frameToman::before,.frameToman::after{position:absolute;right:0;color:#101828;line-height:1}.frameToman::before{content:"ن";top:-.1em}.frameToman::after{content:"توما";bottom:0}.frameProductCard{border:1px solid #dbe5f2;border-radius:16px;background:#fff;padding:16px;min-width:0}.frameProductCard .saleItemHead{display:block}.frameProductCard .pb834ShopGalleryBtn{display:block;width:100%;border:0;background:#f8fafc;border-radius:12px;padding:0}.frameProductCard .saleItemPhoto{display:block;width:100%;height:190px;object-fit:contain;border-radius:12px}.frameProductCard .saleItemInfo{display:grid;gap:6px;margin-top:12px}.frameProductCard .saleItemInfo b{font-size:17px}.frameProductCard .frameSharedDescription{line-height:1.8}.frameProductCard .saleItemPrice{font-size:18px;font-weight:800;margin:14px 0}.frameColorChoices{display:flex;align-items:center;gap:10px;flex-wrap:wrap;grid-column:1/-1}.frameColorCircle{width:26px;height:26px;border-radius:50%;border:1px solid #cbd5e1;background:var(--frame-color);cursor:pointer}.frameColorCircle[aria-pressed=true],.frameColorCircle:focus-visible{outline:3px solid #315efb;outline-offset:3px}.frameStoreChoices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:12px 0}.frameStoreChoices label{font:inherit;display:grid;gap:5px;min-width:0}.frameStoreChoices select{width:100%;min-width:0;font:inherit;border:1px solid #dbe5f2;border-radius:9px;padding:8px;background:#fff}.frameOwnerActions{display:flex;align-items:center;flex-wrap:wrap;gap:10px}.frameOwnerActions button{font:inherit;border:1px solid #dbe5f2;border-radius:9px;padding:9px 14px;background:#fff}.frameOwnerActions .btn{background:#315efb;color:#fff}.frameDeleteModel{color:#b42318}.frameOwnerActions [data-frame-card-message]{width:100%;color:#b42318}#saleItems:has(.frameProductCard),#saleItemsList>.saleItemsGrid:has(.frameProductCard){display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;align-items:start}@media(max-width:1023px){#saleItems:has(.frameProductCard),#saleItemsList>.saleItemsGrid:has(.frameProductCard){grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:639px){#saleItems:has(.frameProductCard),#saleItemsList>.saleItemsGrid:has(.frameProductCard){grid-template-columns:1fr}}@media(max-width:600px){.frameProductCard{padding:12px}.frameStoreChoices{grid-template-columns:1fr}.frameStoreChoices select{font-size:15px}}';}

const api={groups,size,label,version,colorHex,pricingKey,modelColors,pricingRows,choose,changeChoice,price,card,cardStyles};if(typeof module==='object'&&module.exports)module.exports=api;else root.PBFrameCatalog=api;
})(typeof window==='undefined'?globalThis:window);

